#!/usr/bin/env bash
# Question 1: PersistentVolumeClaim ${Q1_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q1_NAME}-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q1_NAME}
    type: DirectoryOrCreate
EOF
kubectl patch pv "${Q1_NAME}-pv" -p '{"spec": {"capacity": {"storage": "2Gi"}}}'
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q1_NAME}-pv-old
  labels: { tier: legacy }
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q1_NAME}-old
    type: DirectoryOrCreate
EOF
kubectl label pv "${Q1_NAME}-pv" tier="${Q1_SELECT_TIER}" --overwrite
